script = r'''
import json, csv
import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq

with open('/data/source_a/users.json') as f:
    source_a_raw = json.load(f)
source_b_raw = list(csv.DictReader(open('/data/source_b/users.csv')))
source_c_raw = pq.read_table('/data/source_c/users.parquet').to_pylist()

FIELD_MAP = {
    'user_id': 'user_id', 'id': 'user_id', 'userId': 'user_id',
    'email': 'email', 'email_address': 'email',
    'full_name': 'name', 'name': 'name', 'userName': 'name',
    'registration_date': 'created_date', 'created_at': 'created_date', 'joined': 'created_date',
    'status': 'status', 'is_active': 'status', 'active': 'status',
}

def normalize(rec):
    out = {}
    for k, v in rec.items():
        if k in FIELD_MAP and v is not None and v != '':
            out[FIELD_MAP[k]] = v
    return out

def fmt_date(v):
    return str(v).strip()[:10]

def fmt_status(v):
    if isinstance(v, bool):
        return 'active' if v else 'inactive'
    if isinstance(v, str) and v.strip().lower() in ('true', 'false'):
        return 'active' if v.strip().lower() == 'true' else 'inactive'
    return v

def make_records(raw):
    res = {}
    for r in raw:
        n = normalize(r)
        n['created_date'] = fmt_date(n.get('created_date')) if 'created_date' in n else None
        n['status'] = fmt_status(n['status']) if 'status' in n else None
        res[n['user_id']] = {k: v for k, v in n.items() if v is not None}
    return res

records_a = make_records(source_a_raw)
records_b = make_records(source_b_raw)
records_c = make_records(source_c_raw)

print('source_a:', records_a)
print('source_b:', records_b)
print('source_c:', records_c)

sources = {'source_a': records_a, 'source_b': records_b, 'source_c': records_c}
priority = ['source_a', 'source_b', 'source_c']
FIELDS = ['user_id', 'name', 'email', 'created_date', 'status']

all_ids = sorted(set(records_a) | set(records_b) | set(records_c))
merged = {}
conflicts = []

for uid in all_ids:
    per_source = {s: sources[s].get(uid, {}) for s in priority}
    row = {'user_id': uid}
    for field in FIELDS:
        vals = {s: per_source[s].get(field) for s in priority}
        selected = None
        for s in priority:
            if vals[s] is not None:
                selected = vals[s]
                break
        row[field] = selected
        present = [vals[s] for s in priority if vals[s] is not None]
        if len(set(present)) > 1:
            conflicts.append({
                'user_id': uid,
                'field': field,
                'values': {s: vals[s] for s in priority},
                'selected': selected,
            })
    merged[uid] = row

rows = [merged[uid] for uid in all_ids]
df = pd.DataFrame(rows, columns=FIELDS)
df['user_id'] = df['user_id'].astype(int)
table = pa.Table.from_pandas(df, schema=pa.schema([
    ('user_id', pa.int64()),
    ('name', pa.string()),
    ('email', pa.string()),
    ('created_date', pa.string()),
    ('status', pa.string()),
]))
pq.write_table(table, '/app/merged_users.parquet')

report = {'total_conflicts': len(conflicts), 'conflicts': conflicts}
with open('/app/conflicts.json', 'w') as f:
    json.dump(report, f, indent=2)

print('Merged rows:')
print(df.to_string())
print('Conflict report:')
print(json.dumps(report, indent=2))
'''
open('/app/merge_users.py', 'w').write(script)
print('script written')
PYEOF
